23	 * REST Controller for Owner operations
24	 */
25	@RestController
26	@RequestMapping("/api/owners")
27	@Tag(name = "Owner", description = "Owner management API")
28	@SecurityRequirement(name = "bearerAuth")
29	public class OwnerRestController {
30	
31		private final OwnerRepository ownerRepository;
32	
33		public OwnerRestController(OwnerRepository ownerRepository) {
34			this.ownerRepository = ownerRepository;
35		}
36	
37		@GetMapping
38		@Operation(summary = "Get all owners", description = "Retrieve a list of all owners")
39		public Collection<Owner> getAllOwners(@RequestParam(required = false) String lastName) {
40			Collection<Owner> owners = ownerRepository.findAll();
41			if (lastName != null && !lastName.isEmpty()) {
42				return owners.stream()
43					.filter(owner -> owner.getLastName().toLowerCase().startsWith(lastName.toLowerCase()))
44					.toList();
45			}
46			return owners;
47		}
48	
49		@GetMapping("/{ownerId}")
50		@Operation(summary = "Get owner by ID", description = "Retrieve a specific owner by their ID")
51		public ResponseEntity<Owner> getOwner(@PathVariable @Parameter(description = "Owner ID") Integer ownerId) {
52			Optional<Owner> owner = ownerRepository.findById(ownerId);
53			return owner.map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());
54		}
55	
56		@PostMapping
57		@Operation(summary = "Create new owner", description = "Create a new owner")
58		public ResponseEntity<Owner> createOwner(@RequestBody Owner owner) {
59			Owner savedOwner = ownerRepository.save(owner);
60			return ResponseEntity.status(HttpStatus.CREATED).body(savedOwner);
61		}
62	
63		@PutMapping("/{ownerId}")
64		@Operation(summary = "Update owner", description = "Update an existing owner")
65		public ResponseEntity<Owner> updateOwner(@PathVariable @Parameter(description = "Owner ID") Integer ownerId,
66				@RequestBody Owner owner) {
67			if (!ownerRepository.existsById(ownerId)) {
68				return ResponseEntity.notFound().build();
69			}
70			owner.setId(ownerId);
71			Owner savedOwner = ownerRepository.save(owner);
72			return ResponseEntity.ok(savedOwner);
73		}
74	
75	}
